  36: func WireLanePacket(candidate RealtimeLaneCandidate) (map[string]any, error) {
  37: 	if err := ValidateRealtimeLanePayload(candidate.Payload); err != nil {
  38: 		return nil, fmt.Errorf("wire lane packet lane=%q family=%q: %w", candidate.Lane(), candidate.PacketFamily(), err)
  39: 	}
  40: 	wire := candidate.Payload.WirePacket()
  41: 	if candidate.MatchID != "" {
  42: 		wire["match_id"] = candidate.MatchID
  43: 	}
  44: 	if err := validateWireLaneMap(candidate, wire); err != nil {
  45: 		return nil, err
  46: 	}
  47: 	return wire, nil
  48: }
  49: 
  50: func validateWireLaneMap(candidate RealtimeLaneCandidate, wire map[string]any) error {
  51: 	if len(wire) == 0 {
  52: 		return fmt.Errorf("wire lane packet lane=%q family=%q: serializer returned empty map", candidate.Lane(), candidate.PacketFamily())
  53: 	}
  54: 	rawType, ok := wire["type"]
  55: 	if !ok {
  56: 		return fmt.Errorf("wire lane packet lane=%q family=%q: missing type", candidate.Lane(), candidate.PacketFamily())
  57: 	}
  58: 	wireType, ok := rawType.(string)
  59: 	if !ok || strings.TrimSpace(wireType) == "" {
  60: 		return fmt.Errorf("wire lane packet lane=%q family=%q: invalid type %v", candidate.Lane(), candidate.PacketFamily(), rawType)
  61: 	}
  62: 	if wireType != candidate.PacketFamily() {
  63: 		return fmt.Errorf("wire lane packet lane=%q family=%q: wire type %q does not match payload family", candidate.Lane(), candidate.PacketFamily(), wireType)
  64: 	}
  65: 	return nil
  66: }
