 172: func wireFilteredRecord(record any, allowedKeys []string) map[string]any {
 173: 	wire := wireValue(record)
 174: 	items, ok := wire.(map[string]any)
 175: 	if !ok {
 176: 		return map[string]any{}
 177: 	}
 178: 	allowed := make(map[string]struct{}, len(allowedKeys))
 179: 	for _, key := range allowedKeys {
 180: 		allowed[key] = struct{}{}
 181: 	}
 182: 	filtered := make(map[string]any, len(allowedKeys))
 183: 	for _, key := range allowedKeys {
 184: 		if value, ok := items[key]; ok {
 185: 			filtered[key] = value
 186: 		}
 187: 	}
 188: 	return filtered
 189: }
