 506: func wireQuantizedEventFloat(fieldPath string, value float64) any {
 507: 	policy, ok := quantize.LookupPolicy(fieldPath)
 508: 	if !ok {
 509: 		return value
 510: 	}
 511: 	encoded, err := quantize.EncodeFloat(policy, value)
 512: 	if err != nil {
 513: 		return value
 514: 	}
 515: 	return encoded
 516: }
