   8: type SendPlan struct {
   9: 	Included []ScheduleRecord
  10: 	Deferred []ScheduleRecord
  11: 	Summary  SendPlanSummary
  12: }
  13: 
  14: func SelectSendPlan(records []ScheduleRecord) SendPlan {
  15: 	ordered := append([]ScheduleRecord(nil), records...)
  16: 	sort.SliceStable(ordered, func(i, j int) bool {
  17: 		return scheduleRank(ordered[i]) < scheduleRank(ordered[j])
  18: 	})
  19: 
  20: 	plan := SendPlan{
  21: 		Included: make([]ScheduleRecord, 0, len(ordered)),
  22: 		Deferred: make([]ScheduleRecord, 0, len(ordered)),
  23: 	}
  24: 
  25: 	budget := TargetBytes
  26: 	for _, record := range ordered {
  27: 		if record.DeliveryClass == DeliveryClassDebugOnly && budget < WarningBytes {
  28: 			continue
  29: 		}
  30: 		budget = appendPlannedRecord(&plan, record, budget)
  31: 	}
  32: 
  33: 	plan.Summary = summarizeSendPlan(plan.Included, plan.Deferred)
  34: 	return plan
  35: }
  36: 
  37: func isRealHotLaneChunkRecord(record ScheduleRecord) bool {
  38: 	return record.Lane == LaneShips || record.Lane == LaneBullets || record.Lane == LaneAsteroids
  39: }
  40: 
  41: func appendPlannedRecord(plan *SendPlan, record ScheduleRecord, budget int) int {
  42: 	estimated := record.EstimatedBytes
  43: 	if estimated <= 0 {
  44: 		estimated = EstimatePacketBytes(record.PacketFamily, 1, 0)
  45: 	}
  46: 
  47: 	if isRequiredRecord(record) || isRealHotLaneChunkRecord(record) {
  48: 		plan.Included = append(plan.Included, record)
  49: 		return budget - estimated
  50: 	}
  51: 
  52: 	if budget-estimated >= 0 {
  53: 		plan.Included = append(plan.Included, record)
  54: 		return budget - estimated
  55: 	}
  56: 
  57: 	plan.Deferred = append(plan.Deferred, record)
  58: 	return budget
  59: }
  60: 
  61: func summarizeSendPlan(included []ScheduleRecord, deferred []ScheduleRecord) SendPlanSummary {
  62: 	summary := SendPlanSummary{
  63: 		IncludedCount: len(included),
  64: 		DeferredCount: len(deferred),
  65: 	}
  66: 
  67: 	for _, record := range included {
  68: 		summary.CreateCount += record.CreateCount
  69: 		summary.UpdateCount += record.UpdateCount
  70: 		summary.DeleteCount += record.DeleteCount
  71: 		summary.RequiredCount += record.RequiredCount
  72: 		summary.SupersededCount += record.SupersededCount
  73: 	}
  74: 
  75: 	return summary
  76: }
  77: 
  78: func scheduleRank(record ScheduleRecord) int {
  79: 	if isRequiredRecord(record) {
  80: 		return laneBootstrapRank(record)
  81: 	}
  82: 	if record.DeliveryClass == DeliveryClassEventOnce || record.PacketFamily == PacketFamilyEventBatch {
  83: 		return 4
  84: 	}
  85: 	if record.Priority == PriorityHigh {
  86: 		return 5
  87: 	}
  88: 	if record.Priority == PriorityMedium {
  89: 		return 6
  90: 	}
  91: 	if record.Lane == LaneSession || record.Priority == PriorityLow {
  92: 		return 7
  93: 	}
  94: 	return 8
  95: }
