  97: func hotPacketCadenceAllows(mode HotLaneMode, sequence int) bool {
  98: 	if sequence <= 0 {
  99: 		sequence = 1
 100: 	}
 101: 	switch mode {
 102: 	case HotLaneModeFullOwned60Hz:
 103: 		return true
 104: 	case HotLaneModeFullOwned30Hz:
 105: 		return sequence%2 == 0
 106: 	case HotLaneModeFullOwned20Hz:
 107: 		return sequence%3 == 0
 108: 	case HotLaneModeFullOwned15Hz:
 109: 		return sequence%4 == 0
 110: 	default:
 111: 		return true
 112: 	}
 113: }
