 277: func (p *WebRTCTransport) SendSmoke(smokeID string, message string) error {
 278: 	return p.SendJSON(map[string]any{
 279: 		"type":     "webrtc_smoke",
 280: 		"smoke_id": smokeID,
 281: 		"origin":   webRTCSmokeOriginServer,
 282: 		"message":  message,
 283: 	})
 284: }
