 286: func (p *WebRTCTransport) Close() error {
 287: 	p.mu.Lock()
 288: 	p.closing = true
 289: 	channels := make([]webRTCDataChannel, 0)
 290: 	for lane, channel := range p.channels {
 291: 		if channel != nil {
 292: 			channels = append(channels, channel)
 293: 		}
 294: 		delete(p.channels, lane)
 295: 	}
 296: 	for lane := range p.readyChannels {
 297: 		delete(p.readyChannels, lane)
 298: 	}
 299: 	p.ready = false
 300: 	peer := p.peer
 301: 	p.mu.Unlock()
 302: 
 303: 	for _, channel := range channels {
 304: 		_ = channel.Close()
 305: 	}
 306: 	if peer != nil {
 307: 		return peer.Close()
 308: 	}
 309: 	return nil
 310: }
 311: 
 312: func (p *WebRTCTransport) attachPeerHandlers() {
 313: 	p.peer.OnICECandidate(func(candidate *webrtc.ICECandidate) {
 314: 		if candidate == nil || p.hooks.OnLocalICECandidate == nil {
 315: 			return
 316: 		}
 317: 		init := candidate.ToJSON()
 318: 		index := 0
 319: 		if init.SDPMLineIndex != nil {
 320: 			index = int(*init.SDPMLineIndex)
 321: 		}
 322: 		media := ""
 323: 		if init.SDPMid != nil {
 324: 			media = *init.SDPMid
 325: 		}
 326: 		p.hooks.OnLocalICECandidate(media, index, init.Candidate)
 327: 	})
 328: }
