 371: func (p *WebRTCTransport) gameplayChannelForLane(lane string) (webRTCDataChannel, error) {
 372: 	if lane == "" {
 373: 		return nil, errors.New("webrtc gameplay lane is required")
 374: 	}
 375: 	if lane == "control" {
 376: 		return nil, errors.New("webrtc control lane is websocket-owned")
 377: 	}
 378: 	if lane == "tooling" {
 379: 		return nil, errors.New("webrtc tooling lane uses dedicated transport API")
 380: 	}
 381: 	if _, ok := webRTCChannelLabelForLane(lane); !ok {
 382: 		return nil, errors.New("webrtc gameplay lane channel is not configured")
 383: 	}
 384: 	p.mu.RLock()
 385: 	channel, ok := p.channels[lane]
 386: 	p.mu.RUnlock()
 387: 	if !ok || channel == nil {
 388: 		return nil, errors.New("webrtc gameplay lane channel is not configured")
 389: 	}
 390: 	if channel.ReadyState() != webrtc.DataChannelStateOpen {
 391: 		return nil, errors.New("webrtc gameplay lane channel is not open")
 392: 	}
 393: 	return channel, nil
 394: }
 395: 
 396: func (p *WebRTCTransport) BufferedAmountForLane(lane string) (uint64, bool) {
 397: 	p.mu.RLock()
 398: 	channel, ok := p.channels[lane]
 399: 	p.mu.RUnlock()
 400: 	if !ok || channel == nil {
 401: 		return 0, false
 402: 	}
 403: 	return channel.BufferedAmount(), true
 404: }
 405: 
 406: func channelWouldExceedBufferedAmount(channel webRTCDataChannel, payloadBytes int) bool {
 407: 	if channel == nil {
 408: 		return false
 409: 	}
 410: 	buffered := channel.BufferedAmount()
 411: 	if buffered >= webRTCMaxBufferedAmountBytes {
 412: 		return true
 413: 	}
 414: 	return uint64(payloadBytes) > webRTCMaxBufferedAmountBytes-buffered
 415: }
 416: 
 417: func (p *WebRTCTransport) toolingChannel() (webRTCDataChannel, error) {
 418: 	p.mu.RLock()
 419: 	channel, ok := p.channels["tooling"]
 420: 	p.mu.RUnlock()
 421: 	if !ok || channel == nil {
 422: 		return nil, errors.New("webrtc tooling lane channel is not configured")
 423: 	}
 424: 	if channel.ReadyState() != webrtc.DataChannelStateOpen {
 425: 		return nil, errors.New("webrtc tooling lane channel is not open")
 426: 	}
 427: 	return channel, nil
 428: }
 429: 
 430: func (p *WebRTCTransport) allRequiredChannelsReadyLocked() bool {
 431: 	for _, spec := range webRTCChannelSpecs() {
 432: 		if !p.readyChannels[spec.Lane] {
 433: 			return false
 434: 		}
 435: 	}
 436: 	return true
 437: }
 438: 
 439: func (p *WebRTCTransport) handleChannelClosed(lane string) {
 440: 	p.mu.Lock()
 441: 	if p.channelCloseReported == nil {
 442: 		p.channelCloseReported = make(map[string]bool)
 443: 	}
 444: 	wasReady := p.readyChannels[lane]
 445: 	if !wasReady || p.channelCloseReported[lane] || p.closing {
 446: 		p.readyChannels[lane] = false
 447: 		p.ready = false
 448: 		p.mu.Unlock()
 449: 		return
 450: 	}
 451: 	p.readyChannels[lane] = false
 452: 	p.ready = false
 453: 	p.channelCloseReported[lane] = true
 454: 	onChannelClosed := p.hooks.OnChannelClosed
 455: 	p.mu.Unlock()
 456: 	if onChannelClosed != nil {
 457: 		onChannelClosed(lane)
 458: 	}
 459: }
 460: 
 461: func (p *WebRTCTransport) handleChannelMessage(lane string, data []byte) error {
 462: 	var packet map[string]any
 463: 	if err := json.Unmarshal(data, &packet); err != nil {
 464: 		return fmt.Errorf("invalid smoke packet json: %w", err)
 465: 	}
 466: 	if p.hooks.OnPacketReceived != nil {
 467: 		p.hooks.OnPacketReceived(packet, lane)
 468: 	}
 469: 	if fmt.Sprint(packet["type"]) == "webrtc_smoke" && p.hooks.OnSmokeReceived != nil {
 470: 		p.hooks.OnSmokeReceived(packet)
 471: 	}
 472: 	return nil
 473: }

