func (state RealtimeLaneState) Metadata() Metadata {
	return Metadata{
		Lane:         state.Lane,
		Sequence:     state.Sequence,
		BaselineID:   state.BaselineID,
		SnapshotID:   state.SnapshotID,
		SnapshotKind: state.SnapshotKind,
