	if packetFamily == "" {
		return
	}
	if state.packetSequences == nil {
		state.packetSequences = make(map[string]int)
	}
	if sequence < state.packetSequences[packetFamily] {
		return
	}
	state.packetSequences[packetFamily] = sequence
